// Two trigger paths merge here. Webhook carries { goal_id } in body;
// schedule carries no body and we pick the first active objective that
// has zero proposed milestones (FIFO by priority, then created_at).
// If nothing eligible, emit { skip: true, reason: 'no_eligible_objective' }
// and downstream nodes short-circuit via the Continue if not skipped guard.
const SUPA = 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1';
const SUPA_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';
const hdr = { apikey: SUPA_KEY, Authorization: `Bearer ${SUPA_KEY}` };

const input = $input.first().json || {};
const body = input.body || input;
let goalId = body && typeof body.goal_id === 'string' ? body.goal_id.trim() : '';
const mode = body && body.mode === 'recalibrate' ? 'recalibrate' : 'propose';
const krishContext = body && typeof body.krish_context === 'string' ? body.krish_context.slice(0, 4000) : '';
let trigger = goalId ? 'webhook' : 'schedule';

if (!goalId) {
  // Schedule path: find first active objective with no proposed milestones.
  const goals = await this.helpers.httpRequest({
    method: 'GET',
    url: `${SUPA}/goals?status=eq.active&select=id,priority,created_at&order=priority.asc.nullslast,created_at.asc&limit=20`,
    headers: hdr,
    json: true,
  });
  for (const g of (goals || [])) {
    const existing = await this.helpers.httpRequest({
      method: 'GET',
      url: `${SUPA}/milestones?goal_id=eq.${encodeURIComponent(g.id)}&status=eq.proposed&select=id&limit=1`,
      headers: hdr,
      json: true,
    });
    if (!Array.isArray(existing) || existing.length === 0) {
      goalId = g.id;
      break;
    }
  }
  if (!goalId) {
    return [{ json: { skip: true, reason: 'no_eligible_objective', trigger } }];
  }
}

return [{ json: { goal_id: goalId, trigger, skip: false, mode, krish_context: krishContext } }];

// Fetch goal row, any existing milestones (for idempotency + sequencing),
// Marcus's brief (so the LLM proposal is grounded in his actual identity),
// and Krish's voice rules. Run in parallel.
const input = $input.first().json || {};
if (input.skip) {
  return [{ json: { skip: true, reason: input.reason || 'skipped_upstream' } }];
}
const goalId = input.goal_id;
if (!goalId) {
  return [{ json: { skip: true, reason: 'missing_goal_id' } }];
}
const mode = input.mode === 'recalibrate' ? 'recalibrate' : 'propose';

const SUPA = 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1';
const SUPA_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';
const hdr = { apikey: SUPA_KEY, Authorization: `Bearer ${SUPA_KEY}` };
const hdrWrite = { apikey: SUPA_KEY, Authorization: `Bearer ${SUPA_KEY}`, 'Content-Type': 'application/json' };

const [goalArr, milestonesArr, marcusArr, voiceArr, contribArr] = await Promise.all([
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/goals?id=eq.${encodeURIComponent(goalId)}&select=*`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/milestones?goal_id=eq.${encodeURIComponent(goalId)}&select=id,title,status,sequence&order=sequence.asc`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/agents?id=eq.marcus&select=brief_content`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/system_config?key=eq.krish_voice_rules&select=value`, headers: hdr, json: true }).catch(() => []),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/goal_agent_contributions?goal_id=eq.${encodeURIComponent(goalId)}&select=agent_id,contribution_note`, headers: hdr, json: true }).catch(() => []),
]);

const goal = Array.isArray(goalArr) && goalArr.length > 0 ? goalArr[0] : null;
if (!goal) {
  return [{ json: { skip: true, reason: 'goal_not_found', goal_id: goalId } }];
}

let milestones = Array.isArray(milestonesArr) ? milestonesArr : [];
const alreadyProposed = milestones.some(m => m.status === 'proposed');
if (alreadyProposed) {
  if (mode !== 'recalibrate') {
    return [{ json: { skip: true, reason: 'already_has_proposed_milestones', goal_id: goalId, count: milestones.length } }];
  }
  await this.helpers.httpRequest({ method: 'PATCH', url: `${SUPA}/milestones?goal_id=eq.${encodeURIComponent(goalId)}&status=eq.proposed`, headers: hdrWrite, body: { status: 'dropped' }, json: true }).catch(() => null);
  milestones = milestones.filter(m => m.status !== 'proposed');
}

const marcusBrief = Array.isArray(marcusArr) && marcusArr.length > 0 ? marcusArr[0].brief_content : '';
const voiceRules = Array.isArray(voiceArr) && voiceArr.length > 0 ? voiceArr[0].value : null;
const contributions = Array.isArray(contribArr) ? contribArr : [];
const nextSequence = (milestones.reduce((m, x) => Math.max(m, x.sequence || 0), 0)) + 1;

return [{ json: {
  skip: false,
  goal_id: goalId,
  trigger: input.trigger || 'unknown',
  mode,
  krish_context: input.krish_context || '',
  goal,
  existing_milestones: milestones,
  contributions,
  next_sequence: nextSequence,
  marcus_brief: marcusBrief,
  voice_rules: voiceRules,
} }];

