={{ JSON.stringify({
  model: 'claude-sonnet-4-6',
  max_tokens: 2400,
  temperature: 0.3,
  system: 'You are Marcus, the mind/make OS strategic COO. You are proposing the milestone sequence for ONE portfolio objective. A milestone is the week-sized chunk Krish blocks deep-work time for: roughly 4 to 12 hours of agent or operator work. Propose 2 to 5 milestones that cover the objective end to end. Each milestone has: title (concise, action-oriented, no em dashes, max 80 chars), description (1 to 2 sentences, why this is the right week-sized chunk), sequence (1..N in execution order), est_deep_work_hours (your honest 4-12 estimate), marcus_reasoning (1 sentence, why this milestone earns its place in the sequence). owner_split is an object { "os": [ { "agent": string, "does": short phrase } ], "krish": [ short phrases ] }: os lists what the contributing agents can drive unattended and each agent MUST be one of the CONTRIBUTING AGENT ids given below, krish lists only the steps that genuinely need Krish himself (the actual sales or relationship conversation, final approval before anything is sent or published, recording, the strategic call). is_accomplishment is true for a real weekly accomplishment and false when this is really a task that belongs at the task layer, not a week of focus. auto_executable_pct is your honest 0 to 100 estimate of how much of this milestone the OS can do without Krish. Return ONLY a JSON object: { "milestones": [ { "title":string, "description":string, "sequence":number, "est_deep_work_hours":number, "marcus_reasoning":string, "owner_split":{ "os":[{ "agent":string, "does":string }], "krish":[string] }, "is_accomplishment":boolean, "auto_executable_pct":number } ] }. No prose, no code fences. Zero em dashes anywhere. Use commas, colons, parentheses, periods, or the words "to" and "and". You are grounded in your own brief below.',
  messages: [{
    role: 'user',
    content: 'MY BRIEF (excerpt of Marcus identity that the OS render pipeline injected):\n' + ($json.marcus_brief || '').slice(0, 12000) + '\n\nKRISH VOICE RULES:\n' + JSON.stringify($json.voice_rules || {}) + '\n\nCONTRIBUTING AGENTS (use these ids in owner_split.os):\n' + JSON.stringify($json.contributions || []) + '\n\nKRISH CONTEXT (his own steer, if any; weight it heavily):\n' + (($json.krish_context || '').slice(0, 4000) || '(none)') + '\n\nOBJECTIVE TO DECOMPOSE:\n' + JSON.stringify({
      id: $json.goal.id,
      title: $json.goal.title,
      venture: $json.goal.venture,
      objective_kind: $json.goal.objective_kind,
      definition_of_done: $json.goal.definition_of_done,
      why_now: $json.goal.why_now,
      target_horizon: $json.goal.target_horizon,
      primary_kpi: $json.goal.primary_kpi,
      secondary_kpi: $json.goal.secondary_kpi,
      is_auto: $json.goal.is_auto,
      source: $json.goal.source
    }) + '\n\nEXISTING MILESTONES (do not duplicate; pick up after sequence ' + ($json.next_sequence || 1) + '):\n' + JSON.stringify($json.existing_milestones || []) + '\n\nReturn the JSON now.'
  }]
}) }}

parameters.jsCode:
// Parse Sonnet output, validate shape, insert into milestones table
// with source=marcus_proposed status=proposed proposed_at=now().
// Idempotency: if any 'proposed' row exists for this goal_id by the time
// we get here (race with another execution), skip the insert.
const SUPA = 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1';
const SUPA_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';
const hdr = { apikey: SUPA_KEY, Authorization: `Bearer ${SUPA_KEY}`, 'Content-Type': 'application/json', Prefer: 'return=representation' };

const llmResp = $input.first().json || {};
const blocks = llmResp.content || [];
const rawText = blocks.map(b => (b && b.text) || '').join('').trim();
let textForParse = rawText;
if (textForParse.startsWith('```')) {
  textForParse = textForParse.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
}
let parsed;
try { parsed = JSON.parse(textForParse); }
catch (e) {
  return [{ json: { ok: false, reason: 'invalid_llm_json', raw: textForParse.slice(0, 2000), error: String(e) } }];
}

const ctx = $('Fetch context').first().json;
const goalId = ctx.goal_id;
const baseSeq = ctx.next_sequence || 1;

const proposed = Array.isArray(parsed.milestones) ? parsed.milestones : [];
const clean = [];
for (let i = 0; i < proposed.length && i < 5; i++) {
  const m = proposed[i] || {};
  const title = String(m.title || '').trim();
  if (!title) continue;
  if (title.includes('\u2014') || title.includes('\u2013')) continue; // em or en dash filter
  const description = String(m.description || '').trim();
  if (description.includes('\u2014') || description.includes('\u2013')) continue;
  const reasoning = String(m.marcus_reasoning || '').trim();
  const seq = Number.isInteger(m.sequence) && m.sequence > 0 ? m.sequence : (baseSeq + i);
  const hrs = Number.isFinite(m.est_deep_work_hours) ? Math.max(1, Math.min(40, Math.round(m.est_deep_work_hours))) : null;
  clean.push({
    goal_id: goalId,
    title: title.slice(0, 200),
    description: description.slice(0, 2000),
    sequence: seq,
    status: 'proposed',
    source: 'marcus_proposed',
    est_deep_work_hours: hrs,
    marcus_reasoning: reasoning.slice(0, 2000),
    owner_split: (m.owner_split && typeof m.owner_split === 'object' && !Array.isArray(m.owner_split)) ? m.owner_split : null,
    is_accomplishment: m.is_accomplishment === false ? false : true,
    auto_executable_pct: Number.isFinite(m.auto_executable_pct) ? Math.max(0, Math.min(100, Math.round(m.auto_executable_pct))) : null,
    proposed_at: new Date().toISOString(),
  });
}

if (clean.length < 2) {
  return [{ json: { ok: false, reason: 'too_few_valid_milestones', count: clean.length, raw: textForParse.slice(0, 2000) } }];
}

// Race-condition idempotency: re-check there are no proposed milestones now.
const raceCheck = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPA}/milestones?goal_id=eq.${encodeURIComponent(goalId)}&status=eq.proposed&select=id&limit=1`,
  headers: hdr,
  json: true,
});
if (Array.isArray(raceCheck) && raceCheck.length > 0) {
  return [{ json: { ok: false, reason: 'lost_race_already_proposed', goal_id: goalId } }];
}

const inserted = await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPA}/milestones`,
  headers: hdr,
  body: clean,
  json: true,
});

await this.helpers.httpRequest({
  method: 'POST',
  url: `${SUPA}/audit_log`,
  headers: hdr,
  body: {
    event_type: 'objective_milestone_proposer',
    actor: 'marcus',
    target: 'milestones',
    details: JSON.stringify({ goal_id: goalId, trigger: ctx.trigger, inserted_count: Array.isArray(inserted) ? inserted.length : 0, base_sequence: baseSeq }),
  },
  json: true,
}).catch(() => null);

return [{ json: { ok: true, goal_id: goalId, trigger: ctx.trigger, inserted_count: Array.isArray(inserted) ? inserted.length : 0, milestones: inserted } }];
